// Auto-generates data/templates/registry.generated.ts from
// data/templates/items/*/template.json.
//
// DO NOT EDIT the generated file manually.
//
// Usage: node scripts/generate-template-registry.mjs

import { readdirSync, readFileSync, existsSync, writeFileSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const ROOT = join(__dirname, "..");
const ITEMS_DIR = join(ROOT, "data", "templates", "items");
const OUTPUT = join(ROOT, "data", "templates", "registry.generated.ts");

function findTemplateJsons(dir) {
  const entries = readdirSync(dir, { withFileTypes: true });
  const results = [];
  for (const entry of entries) {
    if (!entry.isDirectory()) continue;
    const jsonPath = join(dir, entry.name, "template.json");
    if (existsSync(jsonPath)) {
      results.push({ slug: entry.name, path: jsonPath });
    }
  }
  return results;
}

function generateRegistry() {
  if (!existsSync(ITEMS_DIR)) {
    console.log("[templates:registry] items directory not found, generating empty registry.");
    writeFileSync(
      OUTPUT,
      `// AUTO-GENERATED by scripts/generate-template-registry.mjs
// DO NOT EDIT MANUALLY.

const TEMPLATE_REGISTRY: unknown[] = [];

export { TEMPLATE_REGISTRY };
`,
      "utf-8"
    );
    return;
  }

  const found = findTemplateJsons(ITEMS_DIR);

  if (found.length === 0) {
    console.log("[templates:registry] No template JSONs found, generating empty registry.");
    writeFileSync(
      OUTPUT,
      `// AUTO-GENERATED by scripts/generate-template-registry.mjs
// DO NOT EDIT MANUALLY.

const TEMPLATE_REGISTRY: unknown[] = [];

export { TEMPLATE_REGISTRY };
`,
      "utf-8"
    );
    return;
  }

  console.log(`[templates:registry] Found ${found.length} template(s).`);

  const imports = [];
  const entries = [];
  for (const { slug, path } of found) {
    // Use a relative path from the output file's directory
    const relPath = `./items/${slug}/template.json`;
    const varName = `template_${slug.replace(/[^a-zA-Z0-9]/g, "_")}`;
    imports.push(`import ${varName} from "${relPath}";`);
    entries.push(`  ${varName} as unknown,`);
    console.log(`  - ${slug}`);
  }

  const content = `// AUTO-GENERATED by scripts/generate-template-registry.mjs
// DO NOT EDIT MANUALLY.
// Generated at: ${new Date().toISOString()}

${imports.join("\n")}

const TEMPLATE_REGISTRY: unknown[] = [
${entries.join("\n")}
];

export { TEMPLATE_REGISTRY };
`;

  writeFileSync(OUTPUT, content, "utf-8");
  console.log(`[templates:registry] Written to ${OUTPUT}`);
}

generateRegistry();